// v1.0.15 2026-05-31: Accept either OpenAI-compatible (choices[0].message.content) or Ollama-native (message.content / response) chat response shapes.
// Re-attach the original When Called input so downstream nodes (e.g. Parse QA JSON) still see system_prompt/user_content/model/etc.
const inp = $('When Called').first().json;
return $input.all().map((r, i) => {
  const body = r.json || {};
  const out =
    body.choices?.[0]?.message?.content ??
    body.message?.content ??
    body.response ??
    '';
  const baseRaw = $('When Called').all()[i];
  const base = baseRaw ? baseRaw.json : inp;
  return { json: Object.assign({}, base, { output: out }) };
});
